methods.getExchangeRateDisplayFactor:
    /// <summary>
///     Gets the exchange rate display factor for the provided exchange rate currency pair.
/// </summary>
/// <param name="_fromCurrencyCode">
///     The from currency code.
/// </param>
/// <param name="_toCurrencyCode">
///     The to currency code.
/// </param>
/// <param name="_exchangeRateType">
///     The ID of the exchange rate type.
/// </param>
/// <param name="_getReciprocalIfPrimaryNotFound">
///     Determines if the reciprocal exchange rate display factor should be retrieved when the primary exchange
///     rate display factor is not found.
/// </param>
/// <returns>
///     The exchange rate display factor for the provided exchange rate currency pair.
/// </returns>
/// <remarks>
///     It is best to use the <c>ExchangeRateHelper</c> class to retrieve exchange rate information since
///     this method only deals with variable exchange rates and does not take Euro triangulation into account.
/// </remarks>
public static ExchangeRateDisplayFactor getExchangeRateDisplayFactor(
    CurrencyCode _fromCurrencyCode,
    CurrencyCode _toCurrencyCode,
    ExchangeRateTypeRecId _exchangeRateType,
    boolean _getReciprocalIfPrimaryNotFound)
{
    ExchangeRateCurrencyPair exchangeRateCurrencyPair;
    ExchangeRateDisplayFactor exchangeRateDisplayFactor;

    select firstonly ExchangeRateDisplayFactor
        from exchangeRateCurrencyPair
        where exchangeRateCurrencyPair.FromCurrencyCode == _fromCurrencyCode
            && exchangeRateCurrencyPair.ToCurrencyCode == _toCurrencyCode
            && exchangeRateCurrencyPair.ExchangeRateType ==_exchangeRateType;

    exchangeRateDisplayFactor = exchangeRateCurrencyPair.ExchangeRateDisplayFactor;

    if (!exchangeRateDisplayFactor && _getReciprocalIfPrimaryNotFound)
    {
        select firstonly ExchangeRateDisplayFactor
            from exchangeRateCurrencyPair
            where exchangeRateCurrencyPair.FromCurrencyCode == _toCurrencyCode
                && exchangeRateCurrencyPair.ToCurrencyCode == _fromCurrencyCode
                && exchangeRateCurrencyPair.ExchangeRateType ==_exchangeRateType;

        exchangeRateDisplayFactor = exchangeRateCurrencyPair.ExchangeRateDisplayFactor;
    }

    return exchangeRateDisplayFactor;
}

methods.calculateValidToDate:
private date calculateValidToDate()
{
    ExchangeRate exchangeRate;
    validFromDate calculatedToDate = dateMax();
    date validFromDate = this.ValidFrom;
    date validToDate = dateMax();

    select firstonly validtimestate(validFromDate, validToDate) ValidFrom from exchangeRate
        where exchangeRate.ExchangeRateCurrencyPair == this.ExchangeRateCurrencyPair
            && exchangeRate.ValidFrom > this.ValidFrom;

    if (exchangeRate != null)
    {
        calculatedToDate = exchangeRate.ValidFrom - 1;
    }

    return calculatedToDate;
}

methods.findByDate:
/// <summary>
///    Finds the specified record in the <c>ExchangeRate</c> table.
/// </summary>
/// <param name="_exchangeRatePair">
///    The ID of the <c>ExchangeRateCurrencyPair</c> record for which to find the rate.
/// </param>
/// <param name="_validFromDate">
///    The date used to find the exchange rate record.
/// </param>
/// <param name="_forUpdate">
///    The update state of the record retrieved.
/// </param>
/// <returns>
///    The specified record in the <c>ExchangeRate</c> table.
/// </returns>
public static ExchangeRate findByDate(RefRecId _exchangeRatePair, date _validFromDate, boolean _forUpdate = false)
{
    ExchangeRate exchangeRate;
    date validFromDate = _validFromDate;

    exchangeRate.selectForUpdate(_forUpdate);

    select validtimestate(validFromDate) exchangeRate
        where exchangeRate.ExchangeRateCurrencyPair == _exchangeRatePair;

    return exchangeRate;
}

methods.displayStoredExchangeRate_Static:
/// <summary>
/// Retrieves an exchange rate that can be displayed to the user.
/// </summary>
/// <param name="_storedExchangeRate">
/// An exchange rate that is stored in the database.
/// </param>
/// <param name="_exchangeRateDisplayFactor">
/// The exchange rate display factor to apply.
/// </param>
/// <returns>
/// An exchange rate that can be displayed to the user.
/// </returns>
/// <remarks>
/// After users enter exchange rates, they are multiplied by 100 and divided by the exchange rate
/// display factor specified on the <c>ExchangeRateCurrencyPair</c> table, before they are finally
/// stored in the database. This method applies the necessary factor to rates that have been stored in
/// this manner, so that they can be correctly displayed to the user after they are retrieved from the
/// database. It can be called before it displays any exchange rate on a form.
/// </remarks>
public static CurrencyExchangeRate displayStoredExchangeRate_Static(CurrencyExchangeRate _storedExchangeRate, ExchangeRateDisplayFactor _exchangeRateDisplayFactor)
{
    return (_storedExchangeRate / 100) * CurrencyEuroDenomination::getNumericDisplayFactor(_exchangeRateDisplayFactor);
}

methods.prepareExchangeRateForStorage_Static:
/// <summary>
/// Retrieves an exchange rate that can be stored in the database.
/// </summary>
/// <param name="_displayedExchangeRate">
/// An exchange rate that has been entered by the user on a form.
/// </param>
/// <param name="_exchangeRateDisplayFactor">
/// The exchange rate display factor to apply.
/// </param>
/// <returns>
/// An exchange rate that can be stored in the database.
/// </returns>
/// <remarks>
/// After users enter exchange rates, they are multiplied by 100, and divided by the exchange rate
/// display factor that is specified on the <c>ExchangeRateCurrencyPair</c> table, before they are
/// finally stored in the database. This method applies that logic, and has to be called, before
/// storing any exchange rate entered by a user.
/// </remarks>
public static CurrencyExchangeRate prepareExchangeRateForStorage_Static(CurrencyExchangeRate _displayedExchangeRate, ExchangeRateDisplayFactor _exchangeRateDisplayFactor)
{
    return (_displayedExchangeRate * 100) / CurrencyEuroDenomination::getNumericDisplayFactor(_exchangeRateDisplayFactor);
}

methods.getNumericDisplayFactor:
private static int getNumericDisplayFactor(ExchangeRateDisplayFactor _exchangeRateDisplayFactor)
{
    int numericDisplayFactor;

    switch (_exchangeRateDisplayFactor)
    {
        case ExchangeRateDisplayFactor::One:
            numericDisplayFactor = 1;
            break;

        case ExchangeRateDisplayFactor::Ten:
            numericDisplayFactor = 10;
            break;

        case ExchangeRateDisplayFactor::Hundred:
            numericDisplayFactor = 100;
            break;

        case ExchangeRateDisplayFactor::Thousand:
            numericDisplayFactor = 1000;
            break;

        case ExchangeRateDisplayFactor::TenThousand:
            numericDisplayFactor = 10000;
            break;

        default:
            numericDisplayFactor = 1;
            break;
    }

    return numericDisplayFactor;
}

methods.calculateReciprocalExchangeRate:
/// <summary>
/// Calculates the reciprocal exchange rate of a stored exchange rate.
/// </summary>
/// <param name="_exchangeRate">
/// The exchange rate.
/// </param>
/// <returns>
/// The reciprocal exchange rate of a stored exchange rate.
/// </returns>
/// <remarks>
/// The exchange rate that is passed to this method should be in the same form as an exchange rate that
/// is stored in the database. The exchange rate that is returned will be in the same form and could be
/// stored in the database.
/// </remarks>
public static CurrencyExchangeRate calculateReciprocalExchangeRate(CurrencyExchangeRate _exchangeRate)
{
    CurrencyExchangeRate reciprocalExchangeRate = 0;

    if (_exchangeRate)
    {
        // The stored rate must first be divided by 100 to get it into the actual rate before
        // finding the reciprocal. It must be multiplied by 100 to match a rate that would
        // be stored in the database since the rates that are retrieved are always divided
        // by 100 before use.  The math below could be simplified, but was left to be more
        // descriptive about the actual calculation.

        reciprocalExchangeRate = 100 * (1 / (_exchangeRate / 100));
    }

    return reciprocalExchangeRate;
}

methods.getVariableExchangeRate:
/// <summary>
/// Gets the variable exchange rate for the specified exchange rate currency pair.
/// </summary>
/// <param name="_fromCurrencyCode">
/// The from currency code.
/// </param>
/// <param name="_toCurrencyCode">
/// The to currency code.
/// </param>
/// <param name="_exchangeRateType">
/// The ID of the exchange rate type.
/// </param>
/// <param name="_transactionDate">
/// The transaction date.
/// </param>
/// <param name="_getReciprocalIfPrimaryNotFound">
/// Determines whether to retrieve the reciprocal exchange rate when the primary exchange rate is not
/// found.
/// </param>
/// <returns>
/// The variable exchange rate for the specified exchange rate currency pair.
/// </returns>
/// <remarks>
/// It is best to use the <c>ExchangeRateCalculation</c> class to retrieve exchange rate information since
/// this method only deals with variable exchange rates and does not take Euro triangulation into
/// account.
/// </remarks>
public static CurrencyExchangeRate getVariableExchangeRate(
    CurrencyCode _fromCurrencyCode,
    CurrencyCode _toCurrencyCode,
    ExchangeRateTypeRecId _exchangeRateType,
    date _transactionDate,
    boolean _getReciprocalIfPrimaryNotFound)
{
    ExchangeRateCurrencyPair exchangeRateCurrencyPair;
    ExchangeRate exchangeRate;
    CurrencyExchangeRate variableExchangeRate;

    // This call could be included as one SQL statement with a join on the ExchangeRate table,
    // but was broken out for performance reasons. Since the ExchangeRateCurrencyPair table uses
    // a FoundAndEmpty cache, this allows us to skip the SQL call entirely for cases where a
    // reciprocal rate is often used.  We never really know how often a reciprocal rate will be
    // required since it is based on the users data.
    select firstonly RecId
        from exchangeRateCurrencyPair
        where exchangeRateCurrencyPair.FromCurrencyCode == _fromCurrencyCode
            && exchangeRateCurrencyPair.ToCurrencyCode == _toCurrencyCode
            && exchangeRateCurrencyPair.ExchangeRateType ==_exchangeRateType;

    if (exchangeRateCurrencyPair)
    {
        select firstonly validtimestate(_transactionDate) ExchangeRate
            from exchangeRate
            where exchangeRate.ExchangeRateCurrencyPair == exchangeRateCurrencyPair.RecId;

        variableExchangeRate = exchangeRate.ExchangeRate;
    }

    if (_getReciprocalIfPrimaryNotFound && !variableExchangeRate)
    {
        select firstonly RecId
            from exchangeRateCurrencyPair
            where exchangeRateCurrencyPair.FromCurrencyCode == _toCurrencyCode
                && exchangeRateCurrencyPair.ToCurrencyCode == _fromCurrencyCode
                && exchangeRateCurrencyPair.ExchangeRateType ==_exchangeRateType;

        if (exchangeRateCurrencyPair)
        {
            select firstonly validtimestate(_transactionDate) ExchangeRate
                from exchangeRate
                where exchangeRate.ExchangeRateCurrencyPair == exchangeRateCurrencyPair.RecId;
        }

        if (exchangeRate.ExchangeRate)
        {
            // Since the caller asked for the rate in terms of From > To, it must be the reciprocal
            // in order to be accurate.
            variableExchangeRate = ExchangeRateCalculation::calculateReciprocalExchangeRate(exchangeRate.ExchangeRate);
        }
    }

    return variableExchangeRate;
}

methods.calculateTransactionToAccounting:
/// <summary>
///    Calculates the accounting currency amount from the specified transaction currency amount.
/// </summary>
/// <param name="_transactionCurrency">
///    The transaction currency originating the conversion.
/// </param>
/// <param name="_transactionCurrencyAmount">
///    The transaction currency amount that is used to calculate the accounting currency amount.
/// </param>
/// <param name="_roundResult">
///    A Boolean value that determines whether the result should be rounded.
/// </param>
/// <returns>
///    An accounting currency amount that has been calculated from the transaction currency amount
///    with the appropriate rounding applied.
/// </returns>
public AmountMST calculateTransactionToAccounting(CurrencyCode _transactionCurrency, AmountCur _transactionCurrencyAmount, boolean _roundResult)
{
    this.validateLedger();

    // Set the active exchange rate type to 1, which was set to the transaction to accounting exchange rate type
    this.parmActiveExchangeRateType(ActiveExchangeRateType::ExchangeRateType1);

    return this.calculate(
        _transactionCurrency,
        cachedAccountingCurrency,
        _transactionCurrencyAmount,
        _roundResult,
        false);
}

methods.calculateTransactionToAccountingAmounts:
/// <summary>
///    Calculates the accounting currency amount from the specified transaction currency amount.
/// </summary>
/// <param name="_transactionCurrency">
///    The transaction currency originating the conversion.
/// </param>
/// <param name="_transactionCurrencyAmount">
///    The transaction currency amount that is used to calculate the accounting currency amount.
/// </param>
/// <returns>
///    A complex type containing the unrounded and rounded accounting currency amount that has been
///    calculated from the transaction currency amount.
/// </returns>
public CurrencyCalculationResults calculateTransactionToAccountingAmounts(CurrencyCode _transactionCurrency, AmountCur _transactionCurrencyAmount)
{
    Amount unroundedAmount = this.calculateTransactionToAccounting(_transactionCurrency, _transactionCurrencyAmount, false);

    CurrencyCalculationResults amounts;

    // if the amount returned was 0 then no rounding necessary so do an early exit for performance
    if (unroundedAmount == 0)
    {
        amounts = CurrencyCalculationResults::construct(unroundedAmount, unroundedAmount);
    }
    else
    {
        amounts = CurrencyCalculationResults::construct(unroundedAmount,
            this.roundWithRuleTypeCurrencyTableInstance(cachedAccountingCurrency, unroundedAmount));
    }

    return amounts;
}

methods.findByLegalEntity:
/// <summary>
/// Get the primary <c>Ledger</c> record for a legal entity.
/// </summary>
/// <param name="_legalEntityRecId">
/// The record ID of a legal entity.
/// </param>
/// <param name="_forUpdate">
/// A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <param name="_concurrencyModel">
/// The concurrency model option to use when the record is read; optional.
/// </param>
/// <returns>
/// The <c>Ledger</c> record.
/// </returns>
public static Ledger findByLegalEntity(
    LegalEntity _legalEntityRecId,
    boolean _forUpdate = false,
    ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
{
    Ledger ledger;

    ledger.selectForUpdate(_forUpdate);

    if (_forUpdate  && _concurrencyModel != ConcurrencyModel::Auto)
    {
        ledger.concurrencyModel(_concurrencyModel);
    }

    select firstonly ledger
        where ledger.PrimaryForLegalEntity == _legalEntityRecId;

    return ledger;
}

methods.findDataArea:
/// <summary>
///    Finds the specified record in the <c>CompanyInfo</c> table.
/// </summary>
/// <param name="_dataArea">
/// The data area Id' of the record to find.
/// </param>
/// <param name="_forUpdate">
/// A <c>boolean</c> value that indicates if the record should be selected for update; optional.
/// </param>
/// <returns>
///    A record in <c>CompanyInfo</c>; otherwise, an empty record.
/// </returns>
public static CompanyInfo findDataArea(
    SelectableDataArea
    _dataArea, boolean _forUpdate = false)
{
    CompanyInfo companyInfo;

    if (_forUpdate)
    {
        companyInfo.selectForUpdate(_forUpdate);
    }

    if (_dataArea)
    {
        select firstonly companyInfo where companyInfo.DataArea == _dataArea;
    }

    return companyInfo;
}
